head.script:
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurNm, scwin.vIsurNmTpCd, scwin.vDuplCnt;
scwin.gBndApplId;
scwin.gApplDdTm = '', scwin.gAcptDdTm = '';
scwin.processGp; // 파일 연결 1, 파일 삭제 5
scwin.vDelParam = new Object();
scwin.vModParam = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        if (js_usr_tp_cd === '1') {
            // 운영자이면
            btn_Del_File.show("");
        } else {
            btn_Del_File.hide();
        }

        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(pnl_list);
        $c.bns.BnsPanelToGroupBox(pnl_Srch);
        $c.bns.BnsPanelToGroupBox(pnl_AcptSrch);

        // 채권시장조치구분코드
        scwin.setComboCode();

        // 접수 조회 시작일 -7일, 종료일 현재일자로 설정
        edt_ApplStartDd.setValue($c.ut.cGetMinusDate2(scwin.vCurDate, 7));
        edt_ApplEndDd.setValue(scwin.vCurDate);

        // 신청 조회 시작일 -7일, 종료일 현재일자로 설정
        edt_AcptStartDd.setValue($c.ut.cGetMinusDate2(scwin.vCurDate, 30));
        edt_AcptEndDd.setValue(scwin.vCurDate);

        // fn_BndAcptSearch();
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ApplStartDd_onclick
 * @description img_ApplStartDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ApplStartDd_onclick = function() {
    try {
        popUpCalendar2(edt_ApplStartDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.img_ApplStartDd_onclick" });
    }
};

/**
 * @method
 * @name img_ApplEndDd_onclick
 * @description img_ApplEndDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ApplEndDd_onclick = function() {
    try {
        popUpCalendar2(edt_ApplEndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.img_ApplEndDd_onclick" });
    }
};

/**
 * @method
 * @name txb_ApplIsurNm_onkeypress
 * @description txb_ApplIsurNm onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ApplIsurNm_onkeypress = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_ApplStartDd, edt_ApplEndDd)) {
            if (window.event.keyCode === 13) scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.txb_ApplIsurNm_onkeypress" });
    }
};

/**
 * @method
 * @name img_ApplIsurNm_onclick
 * @description img_ApplIsurNm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ApplIsurNm_onclick = function() {
    try {
        scwin.vIsurNmTpCd = 'Appl';
        scwin.vIsurNm = txb_ApplIsurNm.getValue();
        scwin.showIsur(scwin.vIsurNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.img_ApplIsurNm_onclick" });
    }
};

/**
 * @method
 * @name btn_ApplSearch_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ApplSearch_onclick = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_ApplStartDd, edt_ApplEndDd)) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.btn_ApplSearch_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gDelRowChk = false;
        dts_List.setRowPosition(0, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        scwin.gDelRowChk = true;
        scwin.vDelParam.ISUR_CD = dts_List.getCellData(row, "ISUR_CD");
        scwin.vDelParam.APPL_DD = dts_List.getCellData(row, "APPL_DD");
        scwin.vDelParam.APPL_TM = dts_List.getCellData(row, "APPL_TM");
        txb_AcptIsurNm.setValue(dts_List.getCellData(row, "ISUR_NM"));
        scwin.bndAcptSearch(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name grd_List_oncheckclick
 * @description grd_List oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncheckclick = function(col, colid, bCheck) {
    try {
        $c.bns.fn_IsChecked(dts_List, "CHECKED");

        /*
         * 접수번호가 동일한 것들을 모두 체크한다.
         */
        scwin.ctrlCheckBox(col, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.grd_List_oncheckclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        if (dts_List.getRowCount() === 0) return;
        if (row > 0) {
            if (colid === "ORGN_FILE_NM") {
                scwin.fileDownload(row);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.grd_List_OnDblClick" });
    }
};

