/**
 * @method
 * @name dts_AcptList_OnLoadCompleted
 * @description dts_AcptList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_AcptList_OnLoadCompleted = function(rowcount) {
    try {
        let arrPnl = [pnl_AcptSrch];
        $c.bns.CloseWinArrPnl(rowcount, arrPnl, grd_AcptList);
        if (rowcount === 1) {
            dts_AcptList.setCellData(1, "CHECKED", "T");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.dts_AcptList_OnLoadCompleted" });
    }
};

