    try {
        $c.bns.fn_IsChecked(dts_AcptList, "CHECKED");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.grd_AcptList_oncheckclick" });
    }
};

/**
 * @method
 * @name btn_FileCon_onclick
 * @description 「첨부문서연결」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileCon_onclick = async function() {
    try {
        scwin.processGp = 1;
        scwin.gApplDdTm = scwin.applGetApplDdAndTm();
        scwin.gAcptDdTm = scwin.acptGetApplDdAndTm();
        scwin.duplChkFileConn();
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.btn_FileCon_onclick" });
    }
};

/**
 * @method
 * @name dts_AcptList_OnRowPosChanged
 * @description Acpt List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_AcptList_OnRowPosChanged = function(row) {
    try {
        scwin.gBndApplId = dts_AcptList.getCellData(row, "BND_APPL_ID");
        scwin.fileConnSearch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.dts_AcptList_OnRowPosChanged" });
    }
};

/**
