        scwin.gDelRowChk = true;
        scwin.vDelParam.ISUR_CD = dts_ConList.getCellData(row, "ISUR_CD");
        scwin.vDelParam.APPL_DD = dts_ConList.getCellData(row, "APPL_DD");
        scwin.vDelParam.APPL_TM = dts_ConList.getCellData(row, "APPL_TM");
        scwin.vDelParam.BND_APPL_ID = dts_ConList.getCellData(row, "BND_APPL_ID");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20500.grd_ConList_OnClick" });
    }
};

/**
 * @method
 * @name btn_Del_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Del_onclick = async function() {
    try {
        if (dts_ConList.getRowCount() === 0) return;
        scwin.processGp = 5;
        await scwin.del();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.btn_Del_onclick" });
    }
};

/**
 * @method
 * @name btn_Del_File_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Del_File_onclick = async function() {
    try {
        if (dts_List.getRowCount() === 0) return;
        scwin.processGp = 5;
        await scwin.delFile();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.btn_Del_File_onclick" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「파일구분수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mod_onclick = async function() {
    try {
        if (dts_ConList.getRowCount() === 0) return;
        if (scwin.gDelRowChk === false) {
            await $c.win.alert("유가증권신고서 연결정보에서 데이타를 선택하십시오!");
            return;
        }
        scwin.vModParam.ISUR_CD = dts_ConList.getCellData(dts_ConList.getRowPosition(), "ISUR_CD");
        scwin.vModParam.APPL_DD_TM = dts_ConList.getCellData(dts_ConList.getRowPosition(), "APPL_DD_TM");
        scwin.fn_GetPar = scwin.modAttachFileTpCd;
        scwin.fn_SetPar = scwin.setModAttachFileTpCd;
        await scwin.popModAttachFileTpCd(grd_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.processGp === 1) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        }
        if (scwin.processGp === 5) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        }
        dts_List.Reset();
        dts_AcptList.Reset();
        dts_ConList.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === 1) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        }
        if (scwin.processGp === 5) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_FileUp_onclick
 * @description 「파일업로드」 클릭 이벤트
