 * @hidden N
 */
scwin.btn_FileUp_onclick = async function() {
    try {
        scwin.fn_SetPar = scwin.setFileUpLoad;
        await scwin.popFileUpLoad(grd_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20500.btn_FileUp_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
