/**
 * @method
 * @name applGetApplDdAndTm
 * @description 증권신고서 접수정보의 체크된 접수일시 반환
 * @returns {void}
 * @hidden N
 */
scwin.applGetApplDdAndTm = function() {
    let chk = '';
    let returnValApplDd = '',
        returnValApplTm = '',
        returnValIsuCd = '';
    let applDd, applTm;
    const objReturnVal = new Object();
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        chk = dts_List.getCellData(i, "CHECKED");
        if (chk === "T" || chk === "1") {
            applDd = dts_List.getCellData(i, 'APPL_DD_TM').substring(0, 8);
            applTm = dts_List.getCellData(i, 'APPL_DD_TM').substring(8, 17);
            returnValApplDd += "'" + applDd + "',";
            returnValApplTm += "'" + applTm + "',";
            returnValIsuCd += "'" + dts_List.getCellData(i, 'ISUR_CD') + "',";
        }
    }
    objReturnVal.APPL_DD = returnValApplDd.substring(0, returnValApplDd.length - 1);
    objReturnVal.APPL_TM = returnValApplTm.substring(0, returnValApplTm.length - 1);
    objReturnVal.ISUR_CD = returnValIsuCd.substring(0, returnValIsuCd.length - 1);
    return objReturnVal;
};

/**
 * @method
 * @name acptGetApplDdAndTm
 * @description 채권 신청정보의 체크된 접수번호 반환
 * @returns {void}
 * @hidden N
 */
scwin.acptGetApplDdAndTm = function() {
    let chk = '';
    let returnVal = '';
    for (let i = 1; i <= dts_AcptList.getRowCount(); i++) {
        chk = dts_AcptList.getCellData(i, "CHECKED");
        if (chk === "T" || chk === "1") {
            returnVal += "'" + dts_AcptList.getCellData(i, 'BND_APPL_ID') + "',";
        }
    }
    return returnVal.substring(0, returnVal.length - 1);
};

/**
 * @method
 * @name fileConnCheck
 * @description 파일 연결 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileConnCheck = async function() {
    if (scwin.gApplDdTm.APPL_DD === '') {
        await $c.win.alert("유가증권신고서 접수정보에서 연결할 문서를 선택하십시오!");
        return false;
    }
    if (scwin.gAcptDdTm === '') {
        await $c.win.alert("채권신청정보에서 데이타를 선택하십시오!");
        return false;
    }
    return true;
};

/**
 * @method
 * @name insert
 * @description 파일 연결
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    let url;
    if (await scwin.fileConnCheck() === false) return;
    if (!confirm("문서를 연결 하시겠습니까?")) return false;
    if (dts_CheckDuplConList.getRowCount() > 0) {
        await $c.win.alert("이미 문서가 연결되어 있습니다.!");
        return false;
    }
    url = "/bns/FileFaxConn.do?method=processAttachDocConn";
    url += "&SCREN_ID=" + 'ULDBNS20500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&APPL_DD=" + scwin.gApplDdTm.APPL_DD;
    url += "&APPL_TM=" + scwin.gApplDdTm.APPL_TM;
    url += "&ISUR_CD=" + scwin.gApplDdTm.ISUR_CD;
    url += "&BND_APPL_ID=" + scwin.gAcptDdTm;
    url += "&FILE_FAX=" + 'FILE';
    dts_List.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};

