/**
 * @method
 * @name delFile
 * @description 파일 원본 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delFile = async function() {
    if (dts_List.getRowCount() < 1) {
        return;
    }
    if (dts_List.getRowPosition() < 1) {
        await $c.win.alert("삭제할 파일을 선택하세요.");
