/**
 * @method
 * @name fileDownload
 * @description 파일 다운로드
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function(row) {
    if (dts_List.getCellData(row, "FAX_IMG_FILE_NM") === "") {
        return;
    } else {
        let url = "/bns/BnsAttachDocFileDownload.do";
        url += "?ATTACH_FILE_TP_CD=" + 2;
        url += "&ISUR_CD=" + dts_List.getCellData(row, "ISUR_CD");
        const vApplDdTm = dts_List.getCellData(row, "APPL_DD_TM");
        url += "&APPL_DD=" + vApplDdTm.substring(0, 8);
        url += "&APPL_TM=" + vApplDdTm.substring(8, 14);
        location.href = url;
    }
};

