/**
 * @method
 * @name ctrlCheckBox
 * @description 접수번호가 동일한 첨부파일은 모두 선택되도록
 * @param {*} rowNum rowNum
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.ctrlCheckBox = function(rowNum, bCheck) {
    if (bCheck !== "1") {
        return;
    }
    const bnd_appl_id = dts_List.getCellData(rowNum, "BND_APPL_ID");
    if (bnd_appl_id === "") {
        return;
    }
    grd_List.Redraw = false;
    dts_List.setBroadcast(false);
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (bnd_appl_id === dts_List.getCellData(i, 'BND_APPL_ID')) {
            dts_List.setCellData(i, "CHECKED", "T");
        }
    }
    dts_List.setBroadcast(true, true);
    grd_List.Redraw = true;
};

